func main() {
	// RSA certificate
	c, err := x509.ParseCertificate(rsaDER)
	if err != nil {
		fmt.Println("rsa parse err:", err)
		return
	}
	fmt.Println("rsa subject:", c.Subject.CommonName)
	fmt.Println("rsa serial:", c.SerialNumber)
	fmt.Println("rsa version:", c.Version)
	fmt.Println("rsa notbefore:", c.NotBefore.UTC().Format("2006-01-02T15:04:05Z"))
	fmt.Println("rsa notafter:", c.NotAfter.UTC().Format("2006-01-02T15:04:05Z"))
	fmt.Println("rsa sigalg:", c.SignatureAlgorithm)
	fmt.Println("rsa keyusage:", c.KeyUsage)
	fmt.Println("rsa isca:", c.IsCA)
	if rsaPub, ok := c.PublicKey.(*rsa.PublicKey); ok {
		fmt.Println("rsa pubkey ok:", true)
		fmt.Println("rsa pubkey bits:", rsaPub.N.BitLen())
		fmt.Println("rsa pubkey e:", rsaPub.E)
	} else {
		fmt.Println("rsa pubkey ok:", false)
	}

	// ECDSA certificate
	c2, err := x509.ParseCertificate(ecDER)
	if err != nil {
		fmt.Println("ec parse err:", err)
		return
	}
	fmt.Println("ec subject:", c2.Subject.CommonName)
	fmt.Println("ec serial:", c2.SerialNumber)
	if ecPub, ok := c2.PublicKey.(*ecdsa.PublicKey); ok {
		fmt.Println("ec pubkey ok:", true)
		fmt.Println("ec pubkey curve:", ecPub.Curve.Params().Name)
	} else {
		fmt.Println("ec pubkey ok:", false)
	}

	// ParsePKIXPublicKey (standalone)
	pub, err := x509.ParsePKIXPublicKey(rsaSPKI)
	if err != nil {
		fmt.Println("pkix parse err:", err)
	} else if rsaPub, ok := pub.(*rsa.PublicKey); ok {
		fmt.Println("pkix rsa ok:", true)
		fmt.Println("pkix rsa bits:", rsaPub.N.BitLen())
	} else {
		fmt.Println("pkix rsa ok:", false)
	}
}
